t.script:

(function() {
    var inboundOutboundChart = null;
    var warehouseChart = null;
    var categoryValueChart = null;

    function formatCurrency(value) {
        return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD'
        }).format(value);
    }

    function loadDashboardData() {
        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/inventory_dashboard/data', true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        xhr.setRequestHeader('X-Requested-With', 'XMLHttpRequest');
        xhr.onreadystatechange = function() {
            if (xhr.readyState === 4 && xhr.status === 200) {
                try {
                    var data = JSON.parse(xhr.responseText);
                    updateDashboard(data);
                } catch (e) {
                    console.error('Error parsing dashboard data:', e);
                }
            }
        };
        xhr.send(JSON.stringify({}));
    }

    function updateDashboard(data) {
        // Update Executive View cards
        document.getElementById('total-value-exec').textContent = formatCurrency(data.total_stock_value || 0);
        document.getElementById('inventory-turnover').textContent = (data.inventory_turnover || 0).toFixed(2);
        document.getElementById('stock-aging-count').textContent = data.stock_aging_90_days_count || 0;
        document.getElementById('stock-aging-value').textContent = formatCurrency(data.stock_aging_90_days_value || 0);
        document.getElementById('low-stock-count-exec').textContent = data.low_stock_count || 0;

        // Update summary cards (keep for backward compatibility)
        document.getElementById('total-products').textContent = data.total_products || 0;
        document.getElementById('total-value').textContent = formatCurrency(data.total_stock_value || 0);
        document.getElementById('low-stock-count').textContent = data.low_stock_products ? data.low_stock_products.length : 0;
        document.getElementById('total-locations').textContent = data.total_locations || 0;

        // Update low stock table
        var lowStockBody = document.getElementById('low-stock-body');
        if (data.low_stock_products && data.low_stock_products.length > 0) {
            lowStockBody.innerHTML = data.low_stock_products.map(function(p) {
                return '<tr><td><a href="/web#id=' + p.id + '&model=product.product&view_type=form" style="color: #3498db; font-weight: 600; text-decoration: none;">' + p.name + '</a></td><td><strong>' + p.qty_available + '</strong></td><td>' + p.reordering_min_qty + '</td><td><span class="badge badge-warning">Low Stock</span></td></tr>';
            }).join('');
        } else {
            lowStockBody.innerHTML = '<tr><td colspan="4" class="text-center" style="padding: 30px; color: #7f8c8d;">No low stock items</td></tr>';
        }

        // Update recent moves
        var recentMovesBody = document.getElementById('recent-moves-body');
        if (data.recent_moves && data.recent_moves.length > 0) {
            recentMovesBody.innerHTML = data.recent_moves.map(function(m) {
                return '<tr><td style="color: #7f8c8d; font-size: 13px;">' + m.date + '</td><td><strong>' + m.product + '</strong></td><td><span style="color: #27ae60; font-weight: 700;">' + m.quantity + '</span></td><td style="color: #7f8c8d;">' + m.location_from + '</td><td style="color: #7f8c8d;">' + m.location_to + '</td><td style="color: #7f8c8d; font-size: 12px;">' + (m.reference || '-') + '</td></tr>';
            }).join('');
        } else {
            recentMovesBody.innerHTML = '<tr><td colspan="6" class="text-center" style="padding: 30px; color: #7f8c8d;">No recent movements</td></tr>';
        }

        // Update top products
        var topProductsList = document.getElementById('top-products-list');
        if (data.top_products && data.top_products.length > 0) {
            topProductsList.innerHTML = data.top_products.map(function(p, idx) {
                return '<div class="top-product-item"><strong>' + (idx + 1) + '</strong> <a href="/web#id=' + p.id + '&model=product.product&view_type=form">' + p.name + '</a><p>Quantity: <strong>' + p.qty_available + '</strong></p></div>';
            }).join('');
        } else {
            topProductsList.innerHTML = '<p class="text-center" style="color: #7f8c8d; padding: 20px;">No products found</p>';
        }

        // Update warehouses
        var warehouseSummary = document.getElementById('warehouse-summary');
        if (data.warehouses && data.warehouses.length > 0) {
            warehouseSummary.innerHTML = data.warehouses.map(function(w) {
                return '<div class="warehouse-item"><h5><a href="/web#id=' + w.id + '&model=stock.warehouse&view_type=form">' + w.name + '</a></h5><p>Quantity: <strong>' + w.total_qty + '</strong> | Value: <strong>' + formatCurrency(w.total_value) + '</strong></p></div>';
            }).join('');
        } else {
            warehouseSummary.innerHTML = '<p class="text-center" style="color: #7f8c8d; padding: 20px;">No warehouses found</p>';
        }

        // Update categories
        var categorySummary = document.getElementById('category-summary');
        if (data.categories && data.categories.length > 0) {
            categorySummary.innerHTML = data.categories.map(function(c) {
                return '<div class="category-item"><h5><a href="/web#id=' + c.id + '&model=product.category&view_type=form">' + c.name + '</a></h5><p>Products: <strong>' + c.product_count + '</strong> | Quantity: <strong>' + c.total_qty + '</strong></p></div>';
            }).join('');
        } else {
            categorySummary.innerHTML = '<p class="text-center" style="color: #7f8c8d; padding: 20px;">No categories found</p>';
        }

        // Update Top Moving Products
        var topMovingList = document.getElementById('top-moving-products-list');
        if (data.top_moving_products && data.top_moving_products.length > 0) {
            topMovingList.innerHTML = '<div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 15px;">' + 
                data.top_moving_products.map(function(p, idx) {
                    return '<div class="top-product-item"><strong>' + (idx + 1) + '</strong> <a href="/web#id=' + p.id + '&model=product.product&view_type=form">' + p.name + '</a><p>Moved: <strong>' + Math.round(p.quantity_moved) + '</strong> units</p></div>';
                }).join('') + '</div>';
        } else {
            topMovingList.innerHTML = '<p class="text-center" style="color: #7f8c8d; padding: 20px;">No moving products found</p>';
        }

        // Update Slow Moving Items
        var slowMovingBody = document.getElementById('slow-moving-body');
        if (data.slow_moving_items && data.slow_moving_items.length > 0) {
            slowMovingBody.innerHTML = data.slow_moving_items.map(function(p) {
                return '<tr><td><a href="/web#id=' + p.id + '&model=product.product&view_type=form" style="color: #3498db; font-weight: 600; text-decoration: none;">' + p.name + '</a></td><td><strong>' + p.qty_available + '</strong></td><td><strong>' + formatCurrency(p.value) + '</strong></td></tr>';
            }).join('');
        } else {
            slowMovingBody.innerHTML = '<tr><td colspan="3" class="text-center" style="padding: 30px; color: #7f8c8d;">No slow moving items</td></tr>';
        }

        // Create Inbound vs Outbound Chart
        if (data.monthly_inbound_outbound && typeof Chart !== 'undefined') {
            var ctx1 = document.getElementById('inbound-outbound-chart');
            if (ctx1) {
                if (inboundOutboundChart) {
                    inboundOutboundChart.destroy();
                }
                var months = data.monthly_inbound_outbound.map(function(d) { return d.month; });
                var inbound = data.monthly_inbound_outbound.map(function(d) { return d.inbound; });
                var outbound = data.monthly_inbound_outbound.map(function(d) { return d.outbound; });
                inboundOutboundChart = new Chart(ctx1, {
                    type: 'bar',
                    data: {
                        labels: months,
                        datasets: [{
                            label: 'Inbound',
                            data: inbound,
                            backgroundColor: 'rgba(39, 174, 96, 0.7)',
                            borderColor: 'rgba(39, 174, 96, 1)',
                            borderWidth: 2
                        }, {
                            label: 'Outbound',
                            data: outbound,
                            backgroundColor: 'rgba(231, 76, 60, 0.7)',
                            borderColor: 'rgba(231, 76, 60, 1)',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        scales: {
                            y: {
                                beginAtZero: true
                            }
                        }
                    }
                });
            }
        }

        // Create Warehouse Chart
        if (data.warehouses && typeof Chart !== 'undefined') {
            var ctx2 = document.getElementById('warehouse-chart');
            if (ctx2) {
                if (warehouseChart) {
                    warehouseChart.destroy();
                }
                var warehouseNames = data.warehouses.map(function(w) { return w.name; });
                var warehouseValues = data.warehouses.map(function(w) { return w.total_value; });
                warehouseChart = new Chart(ctx2, {
                    type: 'bar',
                    data: {
                        labels: warehouseNames,
                        datasets: [{
                            label: 'Stock Value',
                            data: warehouseValues,
                            backgroundColor: 'rgba(52, 152, 219, 0.7)',
                            borderColor: 'rgba(52, 152, 219, 1)',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        scales: {
                            y: {
                                beginAtZero: true,
                                ticks: {
                                    callback: function(value) {
                                        return formatCurrency(value);
                                    }
                                }
                            }
                        }
                    }
                });
            }
        }

        // Create Category Value Chart
        if (data.category_stock_value && typeof Chart !== 'undefined') {
            var ctx3 = document.getElementById('category-value-chart');
            if (ctx3) {
                if (categoryValueChart) {
                    categoryValueChart.destroy();
                }
                var categoryNames = data.category_stock_value.map(function(c) { return c.name.length > 15 ? c.name.substring(0, 15) + '...' : c.name; });
                var categoryValues = data.category_stock_value.map(function(c) { return c.value; });
                categoryValueChart = new Chart(ctx3, {
                    type: 'doughnut',
                    data: {
                        labels: categoryNames,
                        datasets: [{
                            data: categoryValues,
                            backgroundColor: [
                                'rgba(52, 152, 219, 0.8)',
                                'rgba(39, 174, 96, 0.8)',
                                'rgba(243, 156, 18, 0.8)',
                                'rgba(155, 89, 182, 0.8)',
                                'rgba(231, 76, 60, 0.8)',
                                'rgba(26, 188, 156, 0.8)',
                                'rgba(241, 196, 15, 0.8)',
                                'rgba(230, 126, 34, 0.8)',
                                'rgba(46, 204, 113, 0.8)',
                                'rgba(142, 68, 173, 0.8)'
                            ]
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: true,
                        plugins: {
                            legend: {
                                position: 'right'
                            },
                            tooltip: {
                                callbacks: {
                                    label: function(context) {
                                        return context.label + ': ' + formatCurrency(context.parsed);
                                    }
                                }
                            }
                        }
                    }
                });
            }
        }
    }

    // Load data when page loads
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', loadDashboardData);
    } else {
        loadDashboardData();
    }
})();
